import{f as e,j as t,m as n}from"./runtime-core.esm-bundler-DBPRRnSd.js";import{t as r}from"./plugin-vue_export-helper-CDQIAITX.js";var i=JSON.parse(`{"path":"/notes/%E9%9D%A2%E8%AF%95/my-sql/","title":"MySQL | notes","lang":"zh-CN","frontmatter":{"title":"MySQL","createTime":"2026/04/04 23:28:20","permalink":"/notes/面试/my-sql/","description":"[TOC] mysql中的数据排序是怎么实现的？ MySQL 中的数据排序是怎么实现的？ - MySQL 面试题 - 面试鸭 - 程序员求职面试刷题神器 排序命中索引，使用索引排序，否则使用文件索引 文件排序中，如果数据量少在内存中排序，使用单路排序或双路排序（多个回表的过程） 如果数据大则利用磁盘文件进行外部排序，一般使用归并排序 索引类型有哪些？ ...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"MySQL\\",\\"image\\":[\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250107182533158.png\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250107183211524.png\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250108165951936.png\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250108170015126.png\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250109235346986.png\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250110000914911.png\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250110001516359.png\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250110001528158.png\\"],\\"dateModified\\":\\"2026-06-25T07:15:35.000Z\\",\\"author\\":[]}"],["meta",{"property":"og:url","content":"http://xiaofei.site/notes/%E9%9D%A2%E8%AF%95/my-sql/"}],["meta",{"property":"og:site_name","content":"计算机知识杂货铺"}],["meta",{"property":"og:title","content":"MySQL"}],["meta",{"property":"og:description","content":"[TOC] mysql中的数据排序是怎么实现的？ MySQL 中的数据排序是怎么实现的？ - MySQL 面试题 - 面试鸭 - 程序员求职面试刷题神器 排序命中索引，使用索引排序，否则使用文件索引 文件排序中，如果数据量少在内存中排序，使用单路排序或双路排序（多个回表的过程） 如果数据大则利用磁盘文件进行外部排序，一般使用归并排序 索引类型有哪些？ ..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250107182533158.png"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-06-25T07:15:35.000Z"}],["meta",{"property":"article:modified_time","content":"2026-06-25T07:15:35.000Z"}]]},"readingTime":{"minutes":10.91,"words":3273},"git":{"createdTime":1775331561000,"updatedTime":1782371735000,"contributors":[{"name":"xiaofei","username":"xiaofei","email":"tu_aofei@163.com","commits":1,"avatar":"https://avatars.githubusercontent.com/u/49927991?s=96&v=4","url":"https://github.com/731016"},{"name":"731016","username":"731016","email":"xiaofei00152@gmail.com","commits":1,"avatar":"https://avatars.githubusercontent.com/731016?v=4","url":"https://github.com/731016"}],"changelog":[{"hash":"6226c1c3cfce235348f612b9ec8a011caac82791","time":1782371735000,"email":"xiaofei00152@gmail.com","author":"731016","message":"更新侧边栏配置和图标"},{"hash":"fb8bc3afbb338138170b503192cbdb88a45075bd","time":1775331561000,"email":"tu_aofei@163.com","author":"xiaofei","message":"更新为vuepress"}]},"autoDesc":true,"filePathRelative":"notes/面试/MySQL.md","headers":[],"bulletin":true}`),a={name:`MySQL.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<p>[TOC]</p><h2 id="mysql中的数据排序是怎么实现的" tabindex="-1"><a class="header-anchor" href="#mysql中的数据排序是怎么实现的"><span>mysql中的数据排序是怎么实现的？</span></a></h2><p><a href="https://www.mianshiya.com/bank/1791003439968264194/question/1780933295526146049#heading-7" target="_blank" rel="noopener noreferrer">MySQL 中的数据排序是怎么实现的？ - MySQL 面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p>排序命中索引，使用索引排序，否则使用文件索引</p><p>文件排序中，如果数据量少在内存中排序，使用单路排序或双路排序（多个回表的过程）</p><p>如果数据大则利用磁盘文件进行外部排序，一般使用归并排序</p><h2 id="索引类型有哪些" tabindex="-1"><a class="header-anchor" href="#索引类型有哪些"><span>索引类型有哪些？</span></a></h2><p><a href="https://www.mianshiya.com/bank/1791003439968264194/question/1780933295438065665" target="_blank" rel="noopener noreferrer">MySQL 的索引类型有哪些？ - MySQL 面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p><strong>数据结构</strong></p><ul><li>B+树索引</li><li>哈希索引</li><li>倒排索引（Full-Text）</li><li>R-树索引（多维空间树）</li></ul><p><strong>InnoDB B+树索引</strong></p><ul><li>聚簇索引</li><li>非聚簇索引</li></ul><p><strong>索引性质</strong></p><ul><li>普通索引</li><li>主键索引</li><li>联合索引</li><li>唯一索引</li><li>全文索引</li><li>空间索引</li></ul><h2 id="mysql-innodb引擎中的聚簇索引和非聚簇索引有什么区别" tabindex="-1"><a class="header-anchor" href="#mysql-innodb引擎中的聚簇索引和非聚簇索引有什么区别"><span>mysql InnoDB引擎中的聚簇索引和非聚簇索引有什么区别？</span></a></h2><p><a href="https://www.mianshiya.com/bank/1791003439968264194/question/1780933295442259970#heading-2" target="_blank" rel="noopener noreferrer">MySQL InnoDB 引擎中的聚簇索引和非聚簇索引有什么区别？ - MySQL 面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p>聚簇索引的<code>非叶子节点</code>存储的是<code>索引值</code>，<code>叶子节点</code>存储的是<code>完成的数据记录</code>，一个表只能有一个聚簇索引，一般是表的主键，主要用于范围查询和排序。</p><p>非聚簇索引的<code>非叶子节点</code>存储的也是<code>索引值</code>，<code>叶子节点</code>存储的是<code>数据行的主键</code>和<code>对应的索引列</code>，一个表可以用多个非聚簇索引，非聚簇索引又称为辅助索引，二级索引，主要用于快速定位要查找的列。</p><h2 id="回表是什么" tabindex="-1"><a class="header-anchor" href="#回表是什么"><span>回表是什么？</span></a></h2><p><a href="https://www.mianshiya.com/bank/1791003439968264194/question/1780933295446454273" target="_blank" rel="noopener noreferrer">MySQL 中的回表是什么？ - MySQL 面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p>在使用二级索引（非聚簇索引）作为查询条件时，由于二级索引中只存储索引字段的值和对于的主键。如果要查询数据行中的其它数据，需要根据主键去聚簇索引查询实际的数据行。</p><h2 id="最左前缀匹配原则" tabindex="-1"><a class="header-anchor" href="#最左前缀匹配原则"><span>最左前缀匹配原则</span></a></h2><p><a href="https://www.mianshiya.com/bank/1791003439968264194/question/1780933295450648578" target="_blank" rel="noopener noreferrer">MySQL 索引的最左前缀匹配原则是什么？ - MySQL 面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p>在使用联合索引时，查询条件必须从索引的最左侧开始匹配。</p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250107182533158.png" alt="image-20250107182533158" tabindex="0" loading="lazy"><figcaption>image-20250107182533158</figcaption></figure><h2 id="覆盖索引" tabindex="-1"><a class="header-anchor" href="#覆盖索引"><span>覆盖索引</span></a></h2><p><a href="https://www.mianshiya.com/bank/1791003439968264194/question/1780933295454842881" target="_blank" rel="noopener noreferrer">MySQL 的覆盖索引是什么？ - MySQL 面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p>二级索引中包含了查询所需的所有字段，从而使查询可以仅通过访问二级索引而不需要访问实际的表数据</p><h2 id="索引下推" tabindex="-1"><a class="header-anchor" href="#索引下推"><span>索引下推</span></a></h2><p><a href="https://www.mianshiya.com/bank/1791003439968264194/question/1780933295459037186" target="_blank" rel="noopener noreferrer">MySQL 的索引下推是什么？ - MySQL 面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p>减少回表查询，提高查询效率。允许在使用联合索引查询数据时，将部分查询条件下推到存储引擎层过滤，减少需要从表中读取的数据行，减少IO。</p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250107183211524.png" alt="image-20250107183211524" tabindex="0" loading="lazy"><figcaption>image-20250107183211524</figcaption></figure><h2 id="创建索引需要注意什么" tabindex="-1"><a class="header-anchor" href="#创建索引需要注意什么"><span>创建索引需要注意什么？</span></a></h2><p><a href="https://www.mianshiya.com/bank/1791003439968264194/question/1780933295459037187" target="_blank" rel="noopener noreferrer">在 MySQL 中建索引时需要注意哪些事项？ - MySQL 面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><ol><li>索引不是越多越好，索引会占空间，且每次修改时可能需要维护索引的数据，消耗资源</li><li>对于字段的值有大量重复的谨慎建立索引。比如性别，不绝对，定时任务状态可能需要</li><li>长字段不应该建立索引。text、longtext，占内存大</li><li>数据修改频率远大于查询频率。</li><li>对于需要频繁作为查询条件的字段应该建立索引。如果有多个条件考虑建立联合索引</li><li>经常在order by、group by、distinct后的字段建立索引。</li></ol><h2 id="索引一定有效吗-怎么排查索引效果" tabindex="-1"><a class="header-anchor" href="#索引一定有效吗-怎么排查索引效果"><span>索引一定有效吗？怎么排查索引效果？</span></a></h2><p><a href="https://www.mianshiya.com/bank/1791003439968264194/question/1780933295463231490" target="_blank" rel="noopener noreferrer">MySQL 中使用索引一定有效吗？如何排查索引效果？ - MySQL 面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p><a href="https://www.mianshiya.com/bank/1791003439968264194/question/1780933295509368833" target="_blank" rel="noopener noreferrer">如何使用 MySQL 的 EXPLAIN 语句进行查询分析？ - MySQL 面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p><a href="https://www.mianshiya.com/bank/1791003439968264194/question/1780933295521951745" target="_blank" rel="noopener noreferrer">MySQL 中如何进行 SQL 调优？ - MySQL 面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p><a href="https://www.mianshiya.com/bank/1791003439968264194/question/1805147589229355009" target="_blank" rel="noopener noreferrer">在什么情况下，不推荐为数据库建立索引？ - MySQL 面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p>索引不一定有效</p><p>查询条件不包含索引列、查询条件复杂且不匹配索引的顺序、数据量小的表可能选择全表扫描</p><ul><li>使用联合索引但不符合最左前缀</li><li>索引中使用了运算</li><li>索引上使用了函数</li><li>like使用左侧占位符</li><li>or随意使用</li><li>查询字段类型不匹配导致隐式转换</li><li>不同的参数可能导致索引失效，特别是复杂查询（联表、子查询、需要回表）的情况</li><li>表中两个不同字段进行比较</li><li>使用order by，如果后面跟的不是主键或覆盖索引会导致索引失效</li></ul><p>使用explain命令，查询mysql的执行计划，主要关注</p><p>select_type：SIMPLE(简单查询)/PRIMARY(主查询)/SUBQUERY(子查询)</p><p>type（访问类型）：查询使用的访问方法，ALL（全表扫描）、index、range、ref（非唯一索引）</p><p>key（使用的索引）：如果是NULL，就没使用索引</p><p>rows（扫描的行数）</p><p>Extra（额外信息）：using index（使用覆盖索引）、using where（使用where条件进行过滤）、using temporary（使用临时表）、using filesort（使用文件排序）</p><h2 id="mysql的b-树中查询数据的全过程" tabindex="-1"><a class="header-anchor" href="#mysql的b-树中查询数据的全过程"><span>mysql的B+树中查询数据的全过程</span></a></h2><p><a href="https://www.mianshiya.com/bank/1791003439968264194/question/1780933295471620098#heading-2" target="_blank" rel="noopener noreferrer">请详细描述 MySQL 的 B+ 树中查询数据的全过程 - MySQL 面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><ol><li><p>从根节点开始，根据比较数据键值与节点中存储的索引键值，确定数据在哪个区间，从上到下定位叶子节点</p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250108165951936.png" alt="image-20250108165951936" tabindex="0" loading="lazy"><figcaption>image-20250108165951936</figcaption></figure></li><li><p>叶子节点存储实际的数据行记录，但是一页有16KB,存储的数据不止一条</p></li><li><p>叶子节点中数据行以组的形式划分，利用页目录结构，通过二分查询可定位到对于的组</p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250108170015126.png" alt="image-20250108170015126" tabindex="0" loading="lazy"><figcaption>image-20250108170015126</figcaption></figure></li><li><p>定位组后，利用链表遍历找到对应的数据行</p></li></ol><h2 id="选择b-树作为索引结构" tabindex="-1"><a class="header-anchor" href="#选择b-树作为索引结构"><span>选择B+树作为索引结构？</span></a></h2><p><a href="https://www.mianshiya.com/bank/1791003439968264194/question/1780933295475814402#heading-0" target="_blank" rel="noopener noreferrer">为什么 MySQL 选择使用 B+ 树作为索引结构？ - MySQL 面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><ol><li>高效的查找性能：自平衡树，每个叶子节点到根节点的路径长度相同，插入和删除时会进行分裂和合并，保持树的平衡</li><li>树的高度增长不会过快，使得查询磁盘I/O次数减少：非叶子节点仅保存主键或索引值和页面指针，使得每一页能容纳更多的记录</li><li>范围查询能力强：叶子节点通过链表连接，从根节点定位到叶子节点查询到范围起点后，只需要顺序扫描链表即可遍历后续数据</li></ol><h2 id="mysql事务隔离级别" tabindex="-1"><a class="header-anchor" href="#mysql事务隔离级别"><span>mysql事务隔离级别</span></a></h2><p><a href="https://www.mianshiya.com/bank/1791003439968264194/question/1780933295492591617" target="_blank" rel="noopener noreferrer">MySQL 中的事务隔离级别有哪些？ - MySQL 面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p><a href="https://www.mianshiya.com/bank/1791003439968264194/question/1780933295492591618#heading-0" target="_blank" rel="noopener noreferrer">MySQL 默认的事务隔离级别是什么？为什么选择这个级别？ - MySQL 面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><ol><li>读未提交：可能导致脏读</li><li>读已提交：可能导致不可重复读（同一事务多次查询返回不同的结果）</li><li>可重复读（默认）：可能幻读（同一事务多次查询返回不同数量的行）</li><li>串行化：相当于单线程执行，大大降低并发性能</li></ol><p>兼容早期的binlog的statement格式问题，如果使用读未提交或读已提交会导致主从数据库数据不一致</p><h2 id="mysql发生死锁怎么解决" tabindex="-1"><a class="header-anchor" href="#mysql发生死锁怎么解决"><span>mysql发生死锁怎么解决？</span></a></h2><p><a href="https://www.mianshiya.com/bank/1791003439968264194/question/1780933295505174531#heading-2" target="_blank" rel="noopener noreferrer">MySQL 中如果发生死锁应该如何解决？ - MySQL 面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p>有死锁检测机制，会自动回滚持有资源最少的事务</p><p>锁等待超时参数，获取锁的等待时间超过阈值，就会释放锁进行回滚</p><p>手动kill掉死锁的事务</p><div class="language-mysql line-numbers-mode" data-highlighter="shiki" data-ext="mysql" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-mysql"><span class="line"><span>-- 查询当前正在执行的事务和锁信息</span></span>
<span class="line"><span>show engine innodb status</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- 查询当前锁和锁的等待情况</span></span>
<span class="line"><span>select * from information_schema.Innodb_locks</span></span>
<span class="line"><span>select * from information_schema.Innodb_lock_waits</span></span>
<span class="line"><span></span></span>
<span class="line"><span>通过information_schema的innodb_trx找到事务id和线程id的对应关系</span></span>
<span class="line"><span></span></span>
<span class="line"><span>kill &lt;thread_id&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>MySQL 8.0后</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- 查看当前的锁等待</span></span>
<span class="line"><span>SELECT * FROM performance_schema.data_lock_waits;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- 查看更详细的锁信息</span></span>
<span class="line"><span>SELECT * FROM performance_schema.data_locks;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- 查看当前事务信息</span></span>
<span class="line"><span>SELECT * FROM information_schema.innodb_trx;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- 查看具体的阻塞情况</span></span>
<span class="line"><span>SELECT </span></span>
<span class="line"><span>    waiting_pid AS &#39;等待进程&#39;,</span></span>
<span class="line"><span>    waiting_query AS &#39;等待SQL&#39;,</span></span>
<span class="line"><span>    blocking_pid AS &#39;阻塞进程&#39;,</span></span>
<span class="line"><span>    blocking_query AS &#39;阻塞SQL&#39;,</span></span>
<span class="line"><span>    wait_age AS &#39;等待时间&#39;,</span></span>
<span class="line"><span>    locked_table AS &#39;被锁表&#39;</span></span>
<span class="line"><span>FROM sys.innodb_lock_waits;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="count-、count-1-、count-字段名-有什么区别" tabindex="-1"><a class="header-anchor" href="#count-、count-1-、count-字段名-有什么区别"><span>count(*)、count(1)、count(字段名)有什么区别</span></a></h2><p><a href="https://www.mianshiya.com/bank/1791003439968264194/question/1780933295513563137#heading-0" target="_blank" rel="noopener noreferrer">MySQL 中 count(*)、count(1) 和 count(字段名) 有什么区别？ - MySQL 面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p>count(*)：统计表中所有行的数量，包含null</p><p>count(1)：there is no performance difference，统计表中所有行的数量，包含null</p><p>count(字段名)：统计指定字段不为null的行数。全表扫描，有索引则使用，正常情况下需要判断是否为空，但如果不为空，如是主键，理论上也差不多</p><h2 id="主从同步机制" tabindex="-1"><a class="header-anchor" href="#主从同步机制"><span>主从同步机制</span></a></h2><p><a href="https://www.mianshiya.com/bank/1791003439968264194/question/1780933295538728962#heading-2" target="_blank" rel="noopener noreferrer">什么是 MySQL 的主从同步机制？它是如何实现的？ - MySQL 面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p>主数据库上的数据同步到一个或多个从数据库中</p><p>通过二进制日志（binlog）实现数据的复制。主数据库在执行写操作时，会把操作记录到binlog，推送给从数据库，从数据库重放对应的日志</p><h2 id="主从同步延迟" tabindex="-1"><a class="header-anchor" href="#主从同步延迟"><span>主从同步延迟</span></a></h2><p><a href="https://www.mianshiya.com/bank/1791003439968264194/question/1780933295542923266" target="_blank" rel="noopener noreferrer">如何处理 MySQL 的主从同步延迟？ - MySQL 面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><ul><li><p>二次查询：从库查不到再查询主库</p></li><li><p>强制将写之后立马读的操作转移到主库</p></li><li><p>关键业务读写都在主库</p></li><li><p>使用缓存</p></li></ul><h2 id="深度分页" tabindex="-1"><a class="header-anchor" href="#深度分页"><span>深度分页</span></a></h2><p><a href="https://www.mianshiya.com/bank/1791003439968264194/question/1780933295572283394" target="_blank" rel="noopener noreferrer">MySQL 中如何解决深度分页的问题？ - MySQL 面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p><strong>子查询</strong></p><div class="language-mysql line-numbers-mode" data-highlighter="shiki" data-ext="mysql" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-mysql"><span class="line"><span>select * from user where name = &#39;big&#39; limit 50000,10</span></span>
<span class="line"><span></span></span>
<span class="line"><span>select * from user inner join (select id from user where name = &#39;big&#39; order by id limit 50000,10)</span></span>
<span class="line"><span>as user1 on user.id = user1.id</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>记录id</strong></p><p>记录上一次最大的id，下次查询从这个id开始，适用于自增id，连续查询，如果跳页就会失效</p><h2 id="数据库三大范式" tabindex="-1"><a class="header-anchor" href="#数据库三大范式"><span>数据库三大范式</span></a></h2><p><a href="https://www.mianshiya.com/bank/1791003439968264194/question/1803265470015987713" target="_blank" rel="noopener noreferrer">数据库的三大范式是什么？ - MySQL 面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p>第一范式：不允许重复的列和多指字段</p><p>第二范式：非主键字段必须依赖于整个主键</p><p>第三范式：所有非主键字段只能依赖于主键，不应相互依赖</p><h2 id="varchar-100-和varchar-10-的区别" tabindex="-1"><a class="header-anchor" href="#varchar-100-和varchar-10-的区别"><span>varchar(100)和varchar(10)的区别</span></a></h2><p><a href="https://www.mianshiya.com/bank/1791003439968264194/question/1805142216804081666#heading-1" target="_blank" rel="noopener noreferrer">MySQL 中 VARCHAR(100) 和 VARCHAR(10) 的区别是什么？ - MySQL 面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p>存储的字符串长度上限不同</p><p>存储相同字符串时占用空间相同</p><p>查询时如果有排序，，会按照固定大小的内存块进行保存，varchar(100)占用内存会更多</p><h2 id="exists和in的区别" tabindex="-1"><a class="header-anchor" href="#exists和in的区别"><span>exists和in的区别</span></a></h2><p><a href="https://www.mianshiya.com/bank/1791003439968264194/question/1805162404970700802#heading-4" target="_blank" rel="noopener noreferrer">MySQL 中 EXISTS 和 IN 的区别是什么？ - MySQL 面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250109235346986.png" alt="image-20250109235346986" tabindex="0" loading="lazy"><figcaption>image-20250109235346986</figcaption></figure><h2 id="innodb存储引擎和myisam存储引擎的区别" tabindex="-1"><a class="header-anchor" href="#innodb存储引擎和myisam存储引擎的区别"><span>innodb存储引擎和myisam存储引擎的区别</span></a></h2><p><a href="https://www.mianshiya.com/bank/1791003439968264194/question/1811361310328279041#heading-3" target="_blank" rel="noopener noreferrer">MySQL 中 InnoDB 存储引擎与 MyISAM 存储引擎的区别是什么？ - MySQL 面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p>myisam：不支持事务、行级锁，索引和数据分开存储，不支持崩溃后的安全恢复</p><p>innodb：支持事务、行级锁、外键，可通过redolog日志进行崩溃后的安全恢复</p><h2 id="mysql事务的二阶段提交" tabindex="-1"><a class="header-anchor" href="#mysql事务的二阶段提交"><span>mysql事务的二阶段提交</span></a></h2><p><a href="https://www.mianshiya.com/bank/1791003439968264194/question/1849298413057683458" target="_blank" rel="noopener noreferrer">MySQL 事务的二阶段提交是什么？ - MySQL 面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p>保证redo log和binlog的一致性，在崩溃恢复时不会出现数据丢失或数据不一致</p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250110000914911.png" alt="image-20250110000914911" tabindex="0" loading="lazy"><figcaption>image-20250110000914911</figcaption></figure><h2 id="三层b-树能存多少数据" tabindex="-1"><a class="header-anchor" href="#三层b-树能存多少数据"><span>三层B+树能存多少数据</span></a></h2><p><a href="https://www.mianshiya.com/bank/1791003439968264194/question/1849347477245734913#heading-0" target="_blank" rel="noopener noreferrer">MySQL 三层 B+ 树能存多少数据？ - MySQL 面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p>b+树默认数据页大小为16KB</p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250110001516359.png" alt="image-20250110001516359" tabindex="0" loading="lazy"><figcaption>image-20250110001516359</figcaption></figure><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250110001528158.png" alt="image-20250110001528158" tabindex="0" loading="lazy"><figcaption>image-20250110001528158</figcaption></figure>`,110)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};